    import bisect

#def advanced_monotonic_modp(n: int, p: int):
    if n <= 0:
        return 0
    sequence = [pow(2, i, p) for i in range(n)]
    # Compute LIS
    lis_tails = []
    for x in sequence:
        idx = bisect.bisect_left(lis_tails, x)
        if idx == len(lis_tails):
            lis_tails.append(x)
        else:
            lis_tails[idx] = x
    lis_length = len(lis_tails)
    # Compute LDS by negating the sequence and finding LIS
    neg_sequence = [-x for x in sequence]
    lds_tails = []
    for x in neg_sequence:
        idx = bisect.bisect_left(lds_tails, x)
        if idx == len(lds_tails):
            lds_tails.append(x)
        else:
            lds_tails[idx] = x
    lds_length = len(lds_tails)
    return max(lis_length, lds_length)




