from typing import List

def filter_by_substring(strings: List[str], substring: str) -> int:
    """ Filter an input list of strings only for ones that contain given substring and have a prime length.
    >>> filter_by_substring([], 'a')
    0
    >>> filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a')
    2
    """
    def is_prime(num: int) -> bool:
        if num <= 1:
            return False
        if num == 2:
            return True
        for i in range(2, num):
            if num % i == 0:
                return False
        return True

    filtered = [x for x in strings if substring in x]
    count = 0
    for s in filtered:
        if is_prime(len(s)):
            count += 1
    return count

