from typing import List

def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if not numbers:
        return []
    result = []
    for n in numbers[:-1]:
        result.append(n)
        result.append(delimeter)
    result.append(numbers[-1])
    seen = set()
    unique_result = []
    for num in result:
        if num not in seen:
            seen.add(num)
            unique_result.append(num)
    return unique_result

