def greatest_common_divisor(a: int, b: int) -> bool:
    # Check if a and b are positive integers
    if a <= 0 or b <= 0:
        return False

    # Compute GCD using Euclidean algorithm
    while b:
        a, b = b, a % b
    g = a

    # Check if the GCD is a prime number
    if g < 2:
        return False
    for i in range(2, int(g ** 0.5) + 1):
        if g % i == 0:
            return False
    return True

