total = 0
for gpa in grades:
    # determine letter grade
    if gpa == 4.0:
        letter = "A+"
    elif gpa > 3.7:
        letter = "A"
    elif gpa > 3.3:
        letter = "A-"
    elif gpa > 3.0:
        letter = "B+"
    elif gpa > 2.7:
        letter = "B"
    elif gpa > 2.3:
        letter = "B-"
    elif gpa > 2.0:
        letter = "C+"
    elif gpa > 1.7:
        letter = "C"
    elif gpa > 1.3:
        letter = "C-"
    elif gpa > 1.0:
        letter = "D+"
    elif gpa > 0.7:
        letter = "D"
    elif gpa > 0.0:
        letter = "D-"
    else:
        letter = "E"
    # process the letter
    for i, ch in enumerate(letter, start=1):
        if ch not in {'A', 'E'}:
            total += i
return total
